bool refcount_sub_and_test(unsigned int i, refcount_t *r) /* <=== refcount_sub_and_test */ 
{
	unsigned int old, new, val = atomic_read(&r->refs);

	for (;;) {
		if (unlikely(val == UINT_MAX))
			return false;

		new = val - i;
		if (new > val) {
			REFCOUNT_WARN(new > val, "refcount_t: underflow; use-after-free.\n");
			return false;
		}

		old = atomic_cmpxchg_release(&r->refs, val, new);
		if (old == val)
			break;

		val = old;
	}

	return !new;
}

bool refcount_dec_and_test(refcount_t *r) /* <=== refcount_dec_and_test */ 
{
	return refcount_sub_and_test(1, r);
}

